 const wa=[...(W.items||[]).map(i=>({d:i.d,h:`<b>${i.d}</b> · ${i.t} — ${link(i.url,'source')}`})),...W.filings.map(f=>({d:f.date,h:`<b>${f.date}</b> · ${FN[f.form]||f.form}${f.items?' ('+f.items+')':''} — ${link(f.url,'SEC filing')}${/^4/.test(f.form)?` · <a href="#ownership">${'Ownership · Insiders'}</a>`:''}`})),...W.posts.map(p=>({d:p.sgt.slice(0,10),h:`<b>${p.sgt.slice(0,10)}</b> · ${'Post by @JensenHuang'}${XP[p.id]&&/^\s*\S/.test(XP[p.id].text)?' — “'+XP[p.id].text.split(/[\n.!?]/)[0].slice(0,90)+'”':''} — ${link(p.url,'X')} · <a href="#ownership">${'Ownership · Jensen'}</a>`}))].map((x,i)=>({...x,i})).sort((a,b)=>a.d<b.d?1:a.d>b.d?-1:a.i-b.i);
