 const CAT=(E2.catalysts||[]).map(c=>({d:c.d,w:c.when,t:c.t,u:c.url,s:c.src})).filter(c=>Date.parse(c.d+'T23:59:59+08:00')>=NOW);
 const coming=box('c6','Coming up'+` <small>catalysts, soonest first</small>`,`<ul class="tk">${CAT.map(c=>`<li><b>${c.w}</b> · ${c.t} — ${link(c.u,c.s)}</li>`).join('')}</ul>`,['Firmly scheduled or company-stated items only; times in SGT.']);
