 const week=`<div class="grid as">${box('c6 wncard',"What's new this week"+` <small>${W.from} → ${W.to.slice(0,10)} (SGT dates)</small>`,wl.length?`<ul class="tk week">${wl.join('')}</ul>`:`<p>Nothing material this week.</p>`,[major?'':'No new 8-K, 10-Q or 10-K this week; financial figures elsewhere are unchanged.','Newest first. Items from the last 48 hours are in NVIDIA green with a 48h badge; older items in the 7-day window are grey.',`Headlines from the daily news scan (Mon–Sat); filings and posts built at build time from the SEC EDGAR submissions feed (all forms) and @JensenHuang posts (X, fetched ${W.x_fetched}). 7-day window.`].filter(Boolean))}${coming}</div>`;
