function C_street(){const pn={'0q':'Q3 FY27','+1q':'Q4 FY27','0y':'FY27','+1y':'FY28'};mk('cDrift',{type:'bar',data:{labels:C.periods.map(p=>pn[p.p]),datasets:['7daysAgo','30daysAgo','60daysAgo','90daysAgo'].map((k,i)=>({label:{'7daysAgo':'vs 7d','30daysAgo':'vs 30d','60daysAgo':'vs 60d','90daysAgo':'vs 90d'}[k],data:C.periods.map(p=>+((p.trend.current/p.trend[k]-1)*100).toFixed(2)),backgroundColor:PAL[i]}))},options:{scales:{y:{ticks:{callback:v=>v+'%'}}}}})}


function rolloutHTML(){const R0=D.rollout,Ps=[...new Set(R0.map(r=>r.p))];const PZ={'Data Center':'','Edge Computing':'','Gaming and AI PC':'','Gaming':'','Professional Visualization':'','Automotive and Robotics':'','Automotive':''};
 return box('c12','Product rollout'+` <small>${R0.length} ${'launches, newest first'}</small>`,`<div id="roP" style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:10px"><button class="btn pill" data-v="">${'All'}</button>${Ps.map(p=>`<button class="btn" data-v="${p}">${p} (${R0.filter(r=>r.p===p).length})</button>`).join('')}</div><div id="rotl" style="max-height:620px;overflow-y:auto">${R0.map(r=>`<div class="tli" data-p="${r.p}" style="display:flex;gap:14px;padding:8px 0;border-bottom:1px solid var(--line)"><div style="flex:none;width:92px;color:var(--mut);font-size:12px">${r.d}</div><div style="flex:none;width:150px"><span class="pill">${r.p}</span></div><div style="flex:1">${r.t} ${link(r.url,r.src==='newsroom'?'newsroom':'source')}</div></div>`).join('')}</div>`,['Launch, production and availability items from the Highlights section of each quarterly earnings press release (8-K), dated by filing date; launches after the latest release are added from NVIDIA\'s newsroom (marked “newsroom”). Quoted in English. Platform names follow NVIDIA\'s reporting at the time.'])}
